export const expandedCourseQuestions: Question[] = rows.map(
  ([
    id,
    course,
    subject,
    category,
    difficulty,
    question,
    correct,
    distractors,
  ]) => {
    // Distribute the answer position even when the bank is inspected without shuffling.
    const options = [...distractors];
    options.splice(id % 4, 0, correct);
    return {
      id,
      course,
      subject,
      category,
      difficulty,
      question,
      correct,
      options,
      type: "multiple",
      points: { easy: 100, medium: 200, hard: 400 }[difficulty],
    };
  },
);
